        "steps": [
            {
                "model": "step_model",
                "description": "Как испечь вафли хрустящие в вафельнице? Подготовьте необходимые продукты. Из данного количества у меня получилось 8 штук диаметром около 10 см.",
                "name": "",
                "step_number": 1,
                "unique_code": "8ecb264b58114f12b890a886b441653f"
            },
            {
                "model": "step_model",
                "description": "Масло положите в сотейник с толстым дном. Растопите его на маленьком огне на плите, на водяной бане либо в микроволновке.",
                "name": "",
                "step_number": 2,
                "unique_code": "920b17084c324af8b9ed81bdb0de2a84"
            },
            {
                "model": "step_model",
                "description": "Добавьте в теплое масло сахар. Перемешайте венчиком до полного растворения сахара. От тепла сахар довольно быстро растает.",
                "name": "",
                "step_number": 3,
                "unique_code": "44f9080af5d847fda847ecb511edd45d"
            },
            {
                "model": "step_model",
                "description": "Добавьте в масло яйцо. Предварительно все-таки проверьте масло, не горячее ли оно, иначе яйцо может свариться. Перемешайте яйцо с маслом до однородности.",
                "name": "",
                "step_number": 4,
                "unique_code": "c5ab4f73e76c4b888a4a1e0505b39450"
            },
            {
                "model": "step_model",
                "description": "Всыпьте муку, добавьте ванилин.",
                "name": "",
                "step_number": 5,
                "unique_code": "271f5d90fd494a0ba82f99500c44a0f6"
            },
            {
                "model": "step_model",
                "description": "Перемешайте массу венчиком до состояния гладкого однородного теста.",
                "name": "",
                "step_number": 6,
                "unique_code": "bab27ba49ebc4bbaadad2574abf4889e"
            },
            {
                "model": "step_model",
                "description": "Разогрейте вафельницу по инструкции к ней. У меня очень старая, еще советских времен электровафельница. Она может и не очень красивая, но печет замечательно!",
                "name": "",
                "step_number": 7,
                "unique_code": "064757e72d2b4eebb34f0c60d8a30c8f"
            },
            {
                "model": "step_model",
                "description": "Пеките вафли несколько минут до золотистого цвета. Осторожно откройте вафельницу, она очень горячая! Снимите вафлю лопаткой. Горячая она очень мягкая, как блинчик.",
                "name": "",
                "step_number": 9,
                "unique_code": "1be33858e281451480768ca620d7e90f"
            },
            {
                "model": "step_model",
                "description": "Отварите спагетти в подсоленной воде до состояния al dente, следуя инструкции на упаковке.",
                "name": "",
                "step_number": 1,
                "unique_code": "a91faaaca0c54c4fb3b90f61dd510248"
            },
            {
                "model": "step_model",
                "description": "Пока паста варится, разогрейте сковороду на среднем огне и растопите сливочное масло.",
                "name": "",
                "step_number": 2,
                "unique_code": "19357ce977334742bfe6b4e562e107f2"
            },
            {
                "model": "step_model",
                "description": "Добавьте измельченный чеснок и обжарьте его в течение 1 минуты, пока не появится аромат.",
                "name": "",
                "step_number": 3,
                "unique_code": "34d0a738aa4d4e03a30708ac15a66a7e"
            },
            {
                "model": "step_model",
                "description": "Выложите очищенные креветки на сковороду и жарьте 2-3 минуты до готовности, пока они не станут розовыми.",
                "name": "",
                "step_number": 4,
                "unique_code": "ccf8f91f0d7f47649dd7138ae79d612e"
            },
            {
                "model": "step_model",
                "description": "Влейте сливки в сковороду, убавьте огонь до минимума и аккуратно перемешайте. Варите соус 3-4 минуты, пока он слегка не загустеет. Добавьте тертый пармезан, соль и перец по вкусу.",
                "name": "",
                "step_number": 5,
                "unique_code": "4056bc6787dd417185b5b3573511a6d6"
            },
            {
                "model": "step_model",
                "description": "Слейте воду со спагетти и добавьте их в сковороду с соусом и креветками. Перемешайте, чтобы паста пропиталась соусом.",
                "name": "",
                "step_number": 6,
                "unique_code": "cbe9cb80fae84be3b1b619b5d553d73a"
            },
            {
                "model": "step_model",
                "description": "Подавайте пасту, посыпав свежей петрушкой и дополнительно тертым пармезаном.",
